style.css:
@-moz-document domain("youtube.com"), domain("x.com") {
/* General Styling */
  body {
    background-color: #ff9899 !important;
    color: #fff688 !important;
  }

  /* YouTube Styling */
  ytd-app, ytd-page-manager {
    background-color: #FDC9C9 !important;
  }

  /* Twitter (X) Styling */
  [data-testid="primaryColumn"] {
    background-color: #ff9899 !important;
  }

  [role="button"] {
    color: #ff9899 !important;
  }

  a {
    color: #FDC9C9 !important;
  }
}
